// ============================================================
// NOVA Streaming Platform — Shared Types
// DO NOT EDIT THIS FILE (contract between frontend & backend)
// ============================================================

export type TitleType = 'movie' | 'series';

export interface Episode {
  n: number;
  title: string;
  summary: string;
  durationMinutes: number;
}

export interface Season {
  season: number;
  episodes: Episode[];
}

export interface Title {
  _id: string;
  slug: string;
  title: string;
  type: TitleType;
  year: number;
  maturity: string; // 'G' | 'PG' | 'PG-13' | 'R' | 'TV-MA' | 'TV-14'
  rating: number; // 0-10, one decimal (IMDb style)
  durationMinutes: number; // for movies
  seasons: Season[]; // for series
  genres: string[];
  description: string;
  cast: string[];
  director: string;
  language: string;
  poster: string;
  backdrop: string;
  trailer: string; // video URL
  video: string; // video URL
  featured: boolean;
  trending: boolean;
  isNew: boolean;
  quality: 'HD' | '4K';
  views: number;
  createdAt: string;
}

/** Plan identifier — any slug; the four defaults are free/basic/standard/premium. */
export type PlanId = string;

export interface Plan {
  _id: string;
  id: PlanId;
  name: string;
  price: number; // monthly USD
  quality: string;
  devices: number;
  maxStreams: string;
  perks: string[];
  highlight?: boolean;
}

export interface User {
  _id: string;
  name: string;
  email: string;
  role: 'user' | 'admin';
  avatar: string; // gradient key like 'rose'
  plan: PlanId;
  planExpiry?: string | null;
  banned: boolean;
  createdAt: string;
}

export interface WatchProgressItem {
  titleId: string;
  title: Title;
  progressSeconds: number;
  durationSeconds: number;
  updatedAt: string;
}

export interface HomeRow {
  key: string;
  title: string;
  items: Title[];
}

export interface HomePayload {
  hero: Title[];
  rows: HomeRow[];
  top10: Title[];
  continueWatching: WatchProgressItem[];
}

export interface AdminStats {
  totalUsers: number;
  totalTitles: number;
  totalViews: number;
  watchlistCount: number;
  premiumUsers: number;
  revenueMonthly: number;
  signups: { date: string; count: number }[]; // last 14 days
  viewsByDay: { date: string; count: number }[]; // last 14 days
  genreDist: { genre: string; count: number }[];
  topTitles: { title: Title; views: number }[];
  recentUsers: User[];
}

export interface SiteSettings {
  siteName: string;
  heroAutoplay: boolean;
  maintenanceMode: boolean;
  defaultPlan: PlanId;
}

export interface AuthResponse {
  user: User;
  /** true when this registration created the first (admin) account */
  setup?: boolean;
}

/** Payload of GET /api — service health + first-run state. */
export interface HealthPayload {
  ok: boolean;
  service: string;
  db: {
    configured: boolean;
    connected: boolean;
    dbName: string | null;
    error: string | null;
  };
  /** true = database reachable but has zero users (Set up NOVA flow) */
  needsSetup: boolean | null;
}

export interface ApiError {
  error: string;
}
